package com.ruoyi.framework.audit;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class SemiReleaseAuditTest {
 private record Fixture(AuditRecorder recorder,JdbcTemplate jdbc,Map<String,Object> release){}
 private Fixture fixture(){var j=mock(JdbcTemplate.class);var release=new LinkedHashMap<String,Object>(Map.of("release_id",91L,"inventory_id",77L,"factory_id",7L,"work_order_id",2L,"quantity",4L,"net_weight","40","status","ACTIVE"));when(j.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{String s=a.getArgument(0);if(s.contains("FROM metal_inventory"))return List.of(new LinkedHashMap<>(Map.of("inventory_id",77L,"factory_id",7L,"quantity",4L,"net_weight","40")));if(s.contains("FROM metal_semi_release WHERE request_id"))return List.of();if(s.contains("FROM metal_semi_release WHERE release_id"))return List.of(new LinkedHashMap<>(release));if(s.contains("FROM metal_warehouse WHERE"))throw new AssertionError("must not resolve any warehouse");return List.of();});return new Fixture(new AuditRecorder(j,mock(PlatformTransactionManager.class)),j,release);}
 private AuditContext context(String path){var c=new AuditContext();c.path=path;c.actorId=1L;c.verb="POST";return c;}
 @Test void creationAcceptsLongReturnAndDoesNotConfuseInventoryAndReleaseIds(){var f=fixture();var c=context("/metal/warehouse/inventory/77/semi-release");var before=f.recorder.snapshot(c,Map.of("requestId","uuid"),null);assertTrue(before.containsKey("sourceInventory"));var after=f.recorder.snapshot(c,Map.of("requestId","uuid"),91L);assertTrue(after.containsKey("91"));assertEquals(Set.of(7L),c.factories);assertEquals("metal_semi_release",c.objectType);assertEquals(77L,c.objectIds.get("inventoryId"));assertEquals(91L,c.objectIds.get("releaseId"));}
 @Test void cancellationTracksActualReleaseStatus(){var f=fixture();var c=context("/metal/warehouse/semi-release/91/cancel");assertEquals("ACTIVE",((Map<?,?>)f.recorder.snapshot(c,91L,null).get("91")).get("status"));f.release.put("status","CANCELLED");assertEquals("CANCELLED",((Map<?,?>)f.recorder.snapshot(c,91L,null).get("91")).get("status"));}
 @Test void foreignFactoryIsBoundBeforeReadingSnapshots(){var f=fixture();var c=context("/metal/warehouse/inventory/77/semi-release");c.actorId=2L;c.actorFactory=8L;when(f.jdbc.queryForList("SELECT * FROM metal_inventory WHERE inventory_id=? AND factory_id=?",77L,8L)).thenReturn(List.of());assertTrue(f.recorder.snapshot(c,77L,null).isEmpty());assertTrue(c.factories.isEmpty());}
 @Test void missingActorScopeDoesNotReadObjects(){var f=fixture();var c=context("/metal/warehouse/inventory/77/semi-release");c.actorId=2L;assertTrue(f.recorder.snapshot(c,77L,null).isEmpty());verifyNoInteractions(f.jdbc);}
 @Test void mismatchedReturnedReleaseIsRejected(){var f=fixture();f.release.put("inventory_id",88L);var c=context("/metal/warehouse/inventory/77/semi-release");assertTrue(f.recorder.snapshot(c,77L,91L).isEmpty());assertTrue(c.factories.isEmpty());}
 @Test void numericStringSupportsFullPositiveLongRange(){var f=fixture();f.release.put("release_id",Long.MAX_VALUE);var c=context("/metal/warehouse/inventory/77/semi-release");assertTrue(f.recorder.snapshot(c,77L,Long.toString(Long.MAX_VALUE)).containsKey(Long.toString(Long.MAX_VALUE)));assertDoesNotThrow(()->f.recorder.snapshot(context("/metal/warehouse/inventory/77/semi-release"),77L,"9223372036854775808"));}
}
